/**
 * Deterministic labelled fixtures for the ML tests.
 *
 * ## These are test data, and nothing else
 *
 * Every window here is generated by a formula. None of it is a recording of
 * anybody signing, and no accuracy figure computed from these fixtures says
 * anything about the app's behaviour on a real glove. They exist to prove that
 * the pipeline does arithmetic correctly — that a window is resampled to the
 * same length, that a split never leaks a session, that an activation gate
 * refuses what it should — and where a test result is reported, it says so.
 *
 * ## Why the signs are separable by construction
 *
 * Each fixture sign drives a different flex channel to a different peak, so a
 * linear model can separate them and a test can assert that the classifier
 * learned *something*. A test with overlapping classes would fail for reasons
 * that have nothing to do with the code under test. Where a test needs classes
 * that are hard to separate, it constructs them itself.
 */
import type { SensorSample } from '../src/sensors/types';
import type { GloveSide } from '../src/ble/types';
import { buildWindow } from '../src/ml/window';
import {
  DATASET_VERSION,
  PREPROCESSING_VERSION,
  type FrameVector,
  type LabelDefinition,
  type SampleSource,
  type SensorWindowSample,
} from '../src/ml/types';

/** Flex peaks for three fixture signs. Distinguishable, and nothing more. */
export const FIXTURE_SIGN_PEAKS: Readonly<Record<string, readonly number[]>> = {
  'sign-a': [0.9, 0.1, 0.05, 0.05, 0.05],
  'sign-b': [0.05, 0.85, 0.1, 0.05, 0.05],
  'sign-c': [0.05, 0.05, 0.8, 0.05, 0.3],
};

/** A run of samples for one sign, at a fixed rate, from a given start time. */
export function makeRun(
  signId: keyof typeof FIXTURE_SIGN_PEAKS | string,
  startMs: number,
  options: { readonly frames?: number; readonly hz?: number; readonly side?: GloveSide } = {},
): SensorSample[] {
  const peaks = FIXTURE_SIGN_PEAKS[signId] ?? FIXTURE_SIGN_PEAKS['sign-a']!;
  const frames = options.frames ?? 40;
  const hz = options.hz ?? 20;
  const side = options.side ?? 'right';

  return Array.from({ length: frames }, (_, index) => {
    const phase = index / (frames - 1);
    const flex = peaks.map((peak, channel) => {
      const wave = Math.sin(Math.PI * phase * (1 + channel * 0.2));
      return Math.min(1, Math.max(0, peak * wave + 0.02 * channel));
    });

    return {
      side,
      timestampMs: startMs + (index * 1000) / hz,
      flex: [flex[0]!, flex[1]!, flex[2]!, flex[3]!, flex[4]!] as SensorSample['flex'],
      accel: {
        x: Math.sin(phase * Math.PI * 2) * 0.4,
        y: Math.cos(phase * Math.PI * 2) * 0.3,
        z: 9.8,
      },
      gyro: { x: 0.2 * phase, y: 0.1 * phase, z: 0.05 },
    };
  });
}

/** One stored window, built through the real windowing code. */
export function makeWindowSample(options: {
  readonly id: string;
  readonly labelId: string;
  readonly sessionId: string;
  readonly startMs?: number;
  readonly source?: SampleSource;
  readonly side?: GloveSide;
  readonly languageId?: string;
  readonly approval?: SensorWindowSample['approval'];
  readonly calibrationVersion?: number | null;
  readonly startOffsetMs?: number;
}): SensorWindowSample {
  const built = buildWindow(makeRun(options.labelId, options.startMs ?? 0));
  if (!built.ok) throw new Error(`fixture window refused: ${built.reason}`);

  return {
    id: options.id,
    sessionId: options.sessionId,
    ownerId: null,
    languageId: options.languageId ?? 'isl',
    labelId: options.labelId,
    modality: 'glove-sensor',
    source: options.source ?? 'simulated',
    handContext: 'right',
    approval: options.approval ?? 'approved',
    quality: built.quality,
    capturedAtMs: options.startMs ?? 0,
    calibrationVersion: options.calibrationVersion ?? 1,
    preprocessingVersion: PREPROCESSING_VERSION,
    datasetVersion: DATASET_VERSION,
    fingerprint: `${options.sessionId}|${options.labelId}|${options.id}`,
    rejectionReason: null,
    side: options.side ?? 'right',
    frames: built.frames,
    sourceHz: 20,
  };
}

/**
 * A dataset of several signs across several sessions.
 *
 * `perSign` windows of each sign are placed in each session, so the number of
 * near-duplicates within a session is controlled — which is exactly what the
 * session-grouped split has to cope with.
 */
export function makeDataset(options: {
  readonly signs: readonly string[];
  readonly sessions?: number;
  readonly perSign?: number;
  readonly source?: SampleSource;
  readonly approval?: SensorWindowSample['approval'];
  readonly languageId?: string;
}): SensorWindowSample[] {
  const sessions = options.sessions ?? 3;
  const perSign = options.perSign ?? 3;
  const samples: SensorWindowSample[] = [];

  for (let session = 0; session < sessions; session += 1) {
    for (const sign of options.signs) {
      for (let index = 0; index < perSign; index += 1) {
        samples.push(
          makeWindowSample({
            id: `s${session}-${sign}-${index}`,
            sessionId: `session-${session}`,
            labelId: sign,
            startMs: session * 1_000_000 + index * 10_000,
            source: options.source,
            approval: options.approval,
            languageId: options.languageId,
          }),
        );
      }
    }
  }

  return samples;
}

/** Label definitions for the fixture signs. */
export function makeLabels(ids: readonly string[], languageId = 'isl'): LabelDefinition[] {
  return ids.map((id, index) => ({
    id,
    languageId,
    text: id.toUpperCase(),
    note: null,
    createdAtMs: index,
    createdBy: 'user' as const,
    archivedAtMs: null,
  }));
}

/** Two windows that differ enough to be told apart, for prediction tests. */
export function windowFor(labelId: string): readonly FrameVector[] {
  const built = buildWindow(makeRun(labelId, 0));
  if (!built.ok) throw new Error(`fixture window refused: ${built.reason}`);
  return built.frames;
}

/**
 * A run that sits halfway between two fixture signs.
 *
 * This is the input the "not sure" path exists for: a movement that is equally
 * like two taught signs. It is deliberately *not* a real sign — it is a third
 * point in feature space — so a test can check that the app declines to name it
 * rather than being forced to choose.
 */
export function makeBlendRun(
  a: string,
  b: string,
  startMs = 0,
  options: { readonly frames?: number; readonly hz?: number; readonly side?: GloveSide } = {},
): SensorSample[] {
  const first = makeRun(a, startMs, options);
  const second = makeRun(b, startMs, options);
  const half = (x: number, y: number) => (x + y) / 2;

  return first.map((sample, index) => {
    const other = second[index]!;
    return {
      ...sample,
      flex: sample.flex.map((value, channel) => half(value, other.flex[channel]!)) as SensorSample['flex'],
      accel: {
        x: half(sample.accel.x, other.accel.x),
        y: half(sample.accel.y, other.accel.y),
        z: half(sample.accel.z, other.accel.z),
      },
      gyro: {
        x: half(sample.gyro.x, other.gyro.x),
        y: half(sample.gyro.y, other.gyro.y),
        z: half(sample.gyro.z, other.gyro.z),
      },
    };
  });
}

/** A window halfway between two fixture signs, for the "not sure" tests. */
export function windowBetween(a: string, b: string): readonly FrameVector[] {
  const built = buildWindow(makeBlendRun(a, b));
  if (!built.ok) throw new Error(`fixture window refused: ${built.reason}`);
  return built.frames;
}
